(()=>{const all=(window.__QUESTIONS__||[]).filter(q=>q.correctAnswers&&q.correctAnswers.length);let pool=all.sort(()=>Math.random()-.5).slice(0,26),i=0,wrong=0,correct=0,selected=new Set(),sec=1800;const app=document.getElementById('exam-app');function fmt(s){return Math.floor(s/60)+':'+String(s%60).padStart(2,'0')}function render(){if(wrong>=5)return finish(false,'Ai ajuns la 5 greșeli.');if(i>=pool.length)return finish(correct>=22,'Test finalizat.');const q=pool[i];app.innerHTML='<div class="toolbar"><span class="pill">Întrebarea '+(i+1)+'/26</span><span class="pill">Corecte '+correct+'</span><span class="pill">Greșeli '+wrong+'</span><span class="pill" id="timer">'+fmt(sec)+'</span></div><div class="progress"><span style="width:'+((i)/26*100)+'%"></span></div><h2>'+q.title+'</h2>'+(q.image?'<img class="question-img" src="'+q.image+'" alt="">':'')+'<div class="answers">'+q.answers.map((a,n)=>'<label class="answer"><input type="checkbox" value="'+n+'"> '+String.fromCharCode(65+n)+'. '+a+'</label>').join('')+'</div><button class="btn blue" id="send">Trimite răspunsul</button>';document.getElementById('send').onclick=()=>{const got=[...app.querySelectorAll('input:checked')].map(x=>Number(x.value)).sort().join(',');const need=[...q.correctAnswers].sort().join(',');got===need?correct++:wrong++;i++;render();};}function finish(pass,msg){app.innerHTML='<h2>'+(pass?'Ai trecut ✅':'Ai picat ❌')+'</h2><p class="lead">'+msg+' Corecte: '+correct+'. Greșeli: '+wrong+'.</p><button class="btn blue" onclick="location.reload()">Reîncearcă</button>'}setInterval(()=>{sec--;const t=document.getElementById('timer');if(t)t.textContent=fmt(Math.max(sec,0));if(sec<=0)finish(correct>=22,'Timpul a expirat.')},1000);render();})();